/**
 * The few numbers the interface quotes, taken from the coverage report.
 *
 * `reports/poi-coverage.json` is generated by the harvest merge and is the only
 * place these counts exist; typing them into a component is how a page ends up
 * claiming 156,000 campsites a year after the data said 239,000. Run this after a
 * merge (`npm run poi:report && npm run poi:stats`) and the page follows the data.
 */

import { readFileSync, writeFileSync } from "node:fs";

const report = JSON.parse(readFileSync("reports/poi-coverage.json", "utf8"));
const inCells = report.features.in_cells;
const kinds = Object.entries(inCells);
const places = kinds.reduce((sum, [kind, n]) => (kind === "parking" ? sum : sum + n), 0);
const parking = inCells.parking ?? 0;

const stats = {
  day: report.generated.slice(0, 10),
  extracts: report.coverage.extracts_parsed,
  countries: report.coverage.countries_parsed,
  files: report.features.cells,
  places,
  parkingPlaces: parking,
  total: places + parking,
  bytes: report.features.cell_bytes,
  campsites: inCells.camp ?? 0,
  byKind: Object.fromEntries(kinds),
};

writeFileSync("src/data/poi-stats.json", `${JSON.stringify(stats, null, 2)}\n`);
console.log(
  `poi-stats: ${stats.total.toLocaleString("en-US")} places in ${stats.files.toLocaleString("en-US")} files from ${stats.extracts} extracts`,
);
